#include "BuiltinBrushPresets.hh"
#include <cassert>
#include <iostream>
using namespace bts;
int main(){
 auto bitmap=std::make_shared<AlphaBitmap>();bitmap->width=3;bitmap->height=2;bitmap->name="Unequal α / source";bitmap->pixels={0,.17f,.31f,.52f,.86f,1};
 auto all=default_brush_presets([&](const char *){return bitmap;});assert(all.size()==3);assert(all[0].brush.hardness==1&&all[0].brush.spacing==12);assert(all[1].brush.flow==35&&all[1].brush.pressure_flow);assert(all[2].brush.minimum_size==15&&all[2].brush.minimum_flow==10);

 struct Expected {const char *name;float hardness,spacing,flow,minimum_size,minimum_flow;bool pressure_flow,follow;std::array<float,4> jitter;};
 const std::array<Expected,3> expected{{{"Basic Hard",1,12,100,5,5,false,false,{}},{"Basic Soft",0,10,35,5,5,true,false,{}},{"Basic Hard Pressure",.9f,20,100,15,10,true,false,{}}}};
 for(int i=0;i<3;++i){const auto &e=expected[i];const auto &b=all[i].brush;assert(all[i].name==e.name&&b.hardness==e.hardness&&b.spacing==e.spacing&&b.flow==e.flow&&b.minimum_size==e.minimum_size&&b.minimum_flow==e.minimum_flow&&b.pressure_flow==e.pressure_flow&&b.follow_path==e.follow&&b.jitter.values()==e.jitter&&b.pressure_size&&b.diameter==10&&b.stroke_opacity==100);assert((b.alpha.kind==AlphaKind::Bitmap)==(i>=3));}
 for(const auto &p:all){const auto bytes=write_brush_preset(p);const auto copy=read_brush_preset(bytes);assert(copy.name==p.name&&write_brush_preset(copy)==bytes);}
 BrushPreset p{"Complete custom",{}};auto &b=p.brush;b.alpha.kind=AlphaKind::Bitmap;b.alpha.bitmap=bitmap;b.alpha.inverted=true;b.alpha.uniform=.42;b.alpha.dynamic={71,true,.73f,.23f,.19};b.stencil.resource=b.alpha;b.stencil.tiling=3;b.stencil.offset={-7.1,4.9};b.stencil.scale=.43;b.stencil.angle=-67;b.stencil.overlay=false;b.projected.emplace();b.projected->transform=b.stencil;b.projected->name="projection α";b.projected->weave=true;b.projected->density=123;b.projected->values.bump=-.7;b.values.bump=-.3;b.values.base_color={-2,3.7f,.1f,.65f};b.values.normal={-.6f,.2f,.7f};b.erase=b.ao=b.smudge=b.clone=b.clone_absolute=true;b.displacement=false;b.displacement_value=-.73;b.angle=-13;b.follow_path=true;b.hardness=.31;b.mask_value=.28;b.channels={false,true,false,false,true};b.users={true,false,true,false,true,false,true,false};b.user_values={-.1f,1,2,3,4,5,6,7};b.diameter=17;b.pressure_size=false;b.pressure_flow=true;b.minimum_size=13;b.minimum_flow=37;b.lazy_mouse=true;b.lazy_distance=19;b.spacing=131;b.stroke_opacity=41;b.flow=68;b.jitter={13,29,173,31};b.projection.alignment=BrushAlignment::Camera;b.projection.cull=false;b.projection.angle=73;b.projection.orientation=-1;b.projection.symmetry_ray=true;b.projection.camera_right={0,1,0};b.projection.camera_up={1,0,0};
 const auto bytes=write_brush_preset(p);auto copy=read_brush_preset(bytes);assert(write_brush_preset(copy)==bytes);assert(copy.brush.alpha.bitmap->pixels==bitmap->pixels&&copy.brush.alpha.bitmap->name==bitmap->name);assert(copy.brush.alpha.bitmap==copy.brush.stencil.resource->bitmap&&copy.brush.alpha.bitmap==copy.brush.projected->transform.resource->bitmap);assert(QJsonDocument::fromJson(bytes).object()["alpha_resources"].toArray().size()==1);
 const auto reject=[&](auto edit){auto j=QJsonDocument::fromJson(bytes).object();edit(j);bool failed=false;try{(void)read_brush_preset(QJsonDocument(j).toJson());}catch(const std::exception &){failed=true;}assert(failed);assert(write_brush_preset(copy)==bytes);};
 reject([](auto &j){j["version"]=2;});reject([](auto &j){auto b=j["brush"].toObject();b["unsupported_future_control"]=1;j["brush"]=b;});reject([](auto &j){j.remove("brush");});reject([](auto &j){auto b=j["brush"].toObject();b["flow"]="68";j["brush"]=b;});reject([](auto &j){auto b=j["brush"].toObject();b["channels"]=QJsonArray{true};j["brush"]=b;});reject([](auto &j){auto a=j["alpha_resources"].toArray();auto o=a[0].toObject();o["sha256"]=QString(64,'0');a[0]=o;j["alpha_resources"]=a;});reject([](auto &j){auto a=j["alpha_resources"].toArray();auto o=a[0].toObject();o["width"]=1000000000;a[0]=o;j["alpha_resources"]=a;});
 BrushSettings ink;ink.mask_value=0;ink.values.base_color={.23f,.34f,.45f,1};const auto stock=apply_stock_brush(ink,all[1].brush);assert(stock.mask_value==0&&stock.values==ink.values&&stock.spacing==10);assert(read_brush_preset(bytes).brush.mask_value==b.mask_value);
 std::cout<<"Brush presets: three procedural defaults; complete fields/bitmap exact/shared; malformed atomic rejection; stock ink vs User snapshot PASS\n";
}
